import subprocess
import os
import signal
import time
import csv


def task_func(process_name: str) -> int:
    target = os.path.basename(process_name).lower()
    if not target:
        return 0

    pids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/fo", "csv", "/nh"],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                reader = csv.reader(result.stdout.splitlines())
                for row in reader:
                    if len(row) < 2:
                        continue
                    image_name = row[0].strip().strip('"').lower()
                    if image_name == target:
                        try:
                            pids.append(int(row[1].strip().strip('"')))
                        except ValueError:
                            pass
        else:
            result = subprocess.run(
                ["ps", "-A", "-o", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue
                    name = os.path.basename(parts[1].strip()).lower()
                    if name == target:
                        pids.append(pid)
    except Exception:
        return 0

    if not pids:
        return 0

    current_pid = os.getpid()

    for pid in pids:
        if pid == current_pid:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except PermissionError:
            pass
        except OSError:
            pass

    time.sleep(1)

    stopped = 0
    for pid in pids:
        if pid == current_pid:
            continue
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            stopped += 1
        except PermissionError:
            pass
        except OSError:
            stopped += 1

    return stopped
